"""Assemble review artifacts without changing any scientific threshold."""
import sys, json
from pathlib import Path
from collections import Counter
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from gencad_bench.io import dump, sha, now, state, DATA

def read(path):
    return json.loads((ROOT / path).read_text())

def counts(rows, key):
    return dict(Counter((r[key]['status'] for r in rows)))

def main():
    r = read('results.json')
    r2 = read('rounds/R2/results.json')
    r3 = read('rounds/R3/results.json')
    replay = read('raw/material_map_replay.json')
    old = read('rounds/R1/results.json')
    original = {(x['task_id'], x['generator']): (x['design_sha256'], x['level1']) for x in old['rows']}
    rerun = {(x['task_id'], x['generator']): (x.get('design_sha256'), x['level1']) for x in r['rows']}
    consistency = all((rerun.get(k) == v for (k, v) in original.items()))
    candidate = [x for x in r2['rows'] if x['method'] == 'rounded_access_IFU']
    unique = {x['geometry_id']: x for x in candidate}
    volumes = [x['added_intaglio_volume_mm3'] for x in unique.values()]
    gaps = [x['gap_diagnostic']['max_vertex_gap_mm'] for x in unique.values()]
    r3summary = {method: {key: counts([x for x in r3['rows'] if x['method'] == method], key) for key in ['minimum_film', 'milling', 'maximum_film']} for method in ['original', 'R2_rounded', 'classical_rolling_ball']}
    r['rounds'] = {'R1': dict(taskset_unchanged=True, first_run_designs_and_verdicts_reproduced=consistency, original_result_sha256=sha(ROOT / 'rounds/R1/results.json')), 'R2': dict(result_path='rounds/R2/results.json', sha256=sha(ROOT / 'rounds/R2/results.json'), gates=r2['gates'], n_anatomies=len(unique), n_task_replicas=len(candidate), added_cavity_volume_mm3_range=[min(volumes), max(volumes)], sampled_maximum_film_mm_range=[min(gaps), max(gaps)], clinically_approved=False, wall_s=r2['wall_s']), 'R3': dict(result_path='rounds/R3/results.json', sha256=sha(ROOT / 'rounds/R3/results.json'), gates=r3['gates'], representation_gate_pass=r3.get('representation_gate_pass'), original_task_verdicts_changed=False, summary=r3summary, wall_s=r3['wall_s'], maximum_film_scenario_mm=0.12, clinical_threshold=False)}
    r['material_map_replay'] = {k: v for (k, v) in replay.items() if k != 'rows'}
    r['material_map_replay'].update(result_path='raw/material_map_replay.json', sha256=sha(ROOT / 'raw/material_map_replay.json'), exactness='Inherited tolerance/voxel witness replay; not newly Lean-formalized')
    r['verification_fixtures'] = dict(external_referent=dict(kind='our_own_fixture', locator='tests/test_core.py; tests/test_interfaces.py; tests/test_maxfilm.py', compared_quantity='Analytic cube/plane/triangle predicates and deliberately corrupted inputs; no measured dental truth', refutes_us=True))
    r['external_referents'] += [r2['external_referent'], r3['external_referent']]
    if r['registered_bite']:
        r['external_referents'].append(r['registered_bite']['external_referent'])
    r['cost']['recorded_phases_wall_s_sum'] = r['cost']['run_wall_s'] + r2['wall_s'] + r3['wall_s'] + replay['wall_s']
    r['cost']['sum_scope'] = 'R1 includes tests, geometry and literature/context; plus R2/R3/replay. Excludes plotting/orchestration and human-style source investigation; source preparation separately recorded.'
    r['frozen_predictions'] = dict(path='FROZEN_PREDICTIONS.json', sha256=sha(ROOT / 'FROZEN_PREDICTIONS.json'), frozen_utc=read('FROZEN_PREDICTIONS.json')['frozen_utc'], prospectively_blinded=False)
    r['missing_coverage'] = ['Clinical preparation scans paired with their own closed bite', 'Complete general 3D antagonist/neighbour proof adapter', 'Production CAM holder/fixture/shaft path', 'Setup-matched fracture calibration and independently measured manufactured fit', 'Verified Teeth3DS redistribution licence', 'Secure untrusted-plugin execution']
    r['artifact_inventory'] = dict(path='ARTIFACTS.json', self_hash_included=False)
    dump(ROOT / 'results.json', r)
    table = ['| Baseline | PASS | FAIL | UNKNOWN | INVALID |', '|---|---:|---:|---:|---:|']
    for (name, s) in r['summary'].items():
        table.append(f"| {name} | {s['PASS']} | {s['FAIL']} | {s['UNKNOWN']} | {s['INVALID']} |")
    baseline = '\n'.join(table)
    s3 = ['| Intaglio operation | Minimum film PASS | Milling PASS / FAIL | Maximum film PASS / FAIL |', '|---|---:|---:|---:|']
    for (method, s) in r3summary.items():
        s3.append(f"| {method} | {s['minimum_film'].get('PASS', 0)}/8 | {s['milling'].get('PASS', 0)} / {s['milling'].get('FAIL', 0)} | {s['maximum_film'].get('PASS', 0)} / {s['maximum_film'].get('FAIL', 0)} |")
    scenario = '\n'.join(s3)
    model = r['calibration_summary']['model']
    control = r['calibration_summary']['control']
    demo = f"# DentalGenCAD-Bench: lab demo\n\nThe idea is to evaluate a proposed crown against independent geometry and measurements, with exact digital failures taking precedence over surface similarity. A small, deliberately restricted kernel makes its missing capabilities visible. Run `./run_all.sh` in this directory. The [full interface and licence guide](README_BENCH.md) describes local dependencies and plugin use.\n\n## Results\n\nThe frozen set has **{r['n_tasks']} tasks, {r['n_designs']} baseline designs, eight teeth and two held-out subjects**. Four tooth types are crossed with three manufacturer-specific minimum-dimension rules. Preparations are synthetic and derived from target dimensions. Material replicas do not increase the anatomical sample size.\n\n{baseline}\n\nNo baseline has complete Level-1 approval. The absent patient-linked antagonist keeps otherwise passing designs UNKNOWN. The parametric baseline satisfies all 24 wall checks; its six milling failures are two narrow synthetic incisor cavities repeated across materials. Mirror and population reconstruction also expose wall failures. All per-check counts and material-stratified surface distances are in [the baseline table](BASELINE_RESULTS.md) and [results.json](results.json).\n\n![Digital eligibility, withheld anatomy and published fracture measurements](figures/benchmark.png)\n\nAn intaglio construction with a cylindrical portion and rounded cap repairs **{r2['gates']['new_milling_passes']} task-level milling failures**, with no loss of prior milling passes or minimum-film/wall passes. It adds {min(volumes):.2f}–{max(volumes):.2f} mm³ to cavity volume; sampled maximum intaglio-to-preparation gaps become {min(gaps):.3f}–{max(gaps):.3f} mm. A finite uniform-scaling control fails to repair the two narrow incisor geometries through scale 2.0; this is not a theorem against all scaling.\n\nA separate, preregistered **maximum-film scenario of 0.12 mm** exposes the cost. This is an engineering test value, not a clinical acceptance threshold. The original requirements and verdicts are unchanged:\n\n{scenario}\n\nAll eight enlarged cavities fail this extra fit requirement with exact point witnesses. The classical rolling-ball control also fails it in all eight. Its repaired rational profile is convex, but its submitted discretization still fails milling in two cases. Better tool access alone therefore does not establish a better jointly constrained design.\n\nThe independent fracture data contain **22 published group means from three studies**. Leave-study-out 95% coverage is {model['study_balanced_coverage']:.3f} for the random-intercept model and {control['study_balanced_coverage']:.3f} for the equally informed study-balanced control. Interval scores are {model['study_balanced_interval_score_N']:.1f} N and {control['study_balanced_interval_score_N']:.1f} N respectively; lower is better. Both methods miss all eleven held-out groups of PMC10817558. Different setups prevent design-specific calibration, which remains **{r['calibration_admission']}**. Numeric tables and exact locators are in [published_measurements.json](data/published_measurements.json).\n\n## What does not hold\n\nThere is no clinical winner, measured manufacturing improvement or 10× result. Anatomical RMS is not restoration quality. The two-subject set is a software/reasoning stress test, not a population validation. The synthetic preparations include unusually thin incisors and have not been checked as clinical preparations. Three independently registered bite examples demonstrate reading real paired scans; they are not paired with these Teeth3DS teeth, and their nearest-vertex distances do not measure force or signed contact.\n\nExact certificates concern the submitted decimal geometry, convex domains and ideal spherical tips. Tool holders, fixtures, physical cement behaviour and complete arbitrary 3D collisions remain outside scope. The inherited material-map replay checks {replay['witnesses_replayed']} negative witnesses, {replay['constructors_replayed']} constructors and {replay['destructive_radius_controls_rejected']} injected radius errors, with {len(replay['failures'])} failures; its original numerical assumptions remain. The core runs {r['tests']['tests']} positive/negative/mutation tests with {r['tests']['failures']} failures and {r['tests']['errors']} errors. Tests are fixes, not an external dental reference.\n\nThe next lab experiment needs a patient-linked prepared tooth and closed bite, an identified fabrication setup, then frozen geometry and predictions before fabrication and independent fit measurement. Read the [dataset licences](README_BENCH.md#data-licences-and-privacy): Bits2Bites/Bite2Text CC BY-NC-SA; ToothFairy2 CC BY-SA (unused); STS inherited CC BY 4.0; Teeth3DS licence unresolved and private-only pending source verification. No patient text or photographs are included.\n"
    (ROOT / 'README_DEMO.md').write_text(demo)
    results = f"# Results — independent review pending\n\nCanonical numbers are in [results.json](results.json); all interpretation and the figure are in [README_DEMO.md](README_DEMO.md). Full original per-task outcomes are preserved in `rounds/R1/results.json`.\n\n{baseline}\n\nR1 replay reproduces all original design hashes and Level-1 verdicts: **{consistency}**. Current test count {r['tests']['tests']}, failures {r['tests']['failures']}, errors {r['tests']['errors']}. Fixed task SHA256: `{r['taskset_sha256']}`.\n\nR2 frozen gates: `{json.dumps(r2['gates'])}`. This is a digital manufacturing subclaim, with no complete clinical PASS. R3 frozen gates: `{json.dumps(r3['gates'])}`; rational-control convexity gate: {r3.get('representation_gate_pass')}.\n\n{scenario}\n\nThe modeled maximum-film scenario refutes using the R2 milling gain as a joint-fit gain. It is not a clinical threshold. No original score was changed after seeing R3. The repaired classical control retains two milling failures. Negative and UNKNOWN results remain in the raw denominator.\n\nExternal fracture reference: 22 means / 3 independent studies; LOSO balanced interval score {model['study_balanced_interval_score_N']:.4f} N versus {control['study_balanced_interval_score_N']:.4f} N. Both coverage values {model['study_balanced_coverage']:.4f}. Setup-matched calibration: {r['calibration_admission']}. The requested 2025 marginal-gap DOI remains numerically UNKNOWN.\n\nRecorded computation phases total {r['cost']['recorded_phases_wall_s_sum']:.2f} s; R1 peak RSS {r['cost']['peak_RSS_MiB']:.2f} MiB. Preparation {r['cost']['data_preparation']:.2f} s was recorded separately. Search, source reading, reasoning, first failed runs and plotting are not included in this total; see COMMANDS and retained round logs. No full-cost speedup claim is made.\n\nStatus: **PENDING_INDEPENDENT_REVIEW**. No source or generated graph was modified. Specific missing coverage and the next physical measurement are in HANDOFF.md.\n"
    (ROOT / 'RESULTS.md').write_text(results)
    h2 = f"# R2 handoff\n\nFrozen gates: {r2['gates']}. Exact ball access gains six material-task passes on two anatomical preparations; all 24 new candidates pass minimum cement and wall. Zero complete Level-1 approvals. Added cavity volume {min(volumes):.3f}–{max(volumes):.3f} mm³, sampled maximum gap {min(gaps):.3f}–{max(gaps):.3f} mm. All 11 uniform scales fail milling for both thin incisors; the other six shapes already pass at scale 1. Preserve every control trial in rounds/R2/results.json.\n\nThe first oversized-cutter mutation returned UNKNOWN because the empty erosion cannot be projected onto. PREREG_R2_VALIDATION froze an exact Farkas fallback, using the existing insertion parent code. The corrected test rejects the oversized ball; the original failed test log is retained. This changed witness discovery, not a scientific threshold.\n\nNext construction: separately preregister maximum-film certificates and a classical rolling-ball control. Minimum clearance alone cannot validate fit. See PREREG_R3 and retained initial R3 outcomes.\n"
    (ROOT / 'HANDOFF_R2.md').write_text(h2)
    h3 = f"# R3 / foundation handoff\n\nCompleted: one-command package, JSON schemas/plugin, 24 frozen tasks/72 default designs, three baselines, scoped exact milling and cement certificates, inherited D/K/O/P adapters, 22 published fracture group means, three marginal-gap rows, three measured-pose ZIP imports, tables, figure and {r['tests']['tests']} passing tests. Review remains PENDING_INDEPENDENT_REVIEW.\n\nR1: mirror 20 FAIL/4 UNKNOWN; population 14 FAIL/10 UNKNOWN; parametric 6 FAIL/18 UNKNOWN. No whole-task PASS; missing same-patient antagonist/neighbours is explicit. Original designs/verdicts reproduced: {consistency}. Source hashes and the frozen task set are unchanged.\n\nR2: six new milling passes, no previous-pass regressions and no minimum-film/wall regressions. Larger cavities add {min(volumes):.2f}–{max(volumes):.2f} mm³ and permit excessive space. Finite scaling fails for both thin incisors; no global optimality claim.\n\nR3: original cavities maximum-film PASS 8/8; R2 cavities FAIL 8/8 under the NEW modeled 0.12 mm maximum. Classical control: maximum-film FAIL 8/8, milling PASS 6/8 and FAIL 2/8. The first control representation gave seven convexity UNKNOWNs; preserve rounds/R3/initial_results.json. PREREG_R3_V2 changed only its rational discretization. Convexity now passes 8/8 without changing R1/R2. Neither changed construction satisfies both milling and the added fit scenario on every anatomy.\n\nExternal reference limits: two anatomical subjects are not a population; synthetic thin preparation is not measured preparation. Fracture LOSO uses three studies with unmatched support/cement/thickness/ageing; both methods miss all eleven groups of PMC10817558. No design-specific calibrated strength. Missing 2025 review table remains UNKNOWN. Clinical geometry and physical manufacturing have not been joined or validated.\n\nExact replay: `./run_all.sh`; default under four threads, no GPU; all source arrays and raw certificates hash-bound. Read README_DEMO first, then DESIGN/addenda for proof domain. One-command outputs are deterministic in decisions; timing and timestamped run directories vary. Original failure and intermediate evidence are retained.\n\nNext construction to preregister: a joint cavity feasibility problem requiring min/max film and ball coverage on a measured prepared tooth, plus its own registered antagonist. First acquire/locate a matched local scan pair and an independently measured fit quantity; do not fabricate a preparation label or join subjects. Compare the submitted decimal geometry and float32/manufactured result explicitly. Freeze predictions before any measurement. A missing fit pair is an evidence gap, not permission to infer clinical success.\n\nGraph coverage proposal (definition only): extend DENT-VAL-BASELINE-COMPARISON with generator-owned geometry / evaluator-owned evidence contracts; separate nodes for exact convex ball-access, full 3D antagonist/neighbour proof, and joint internal-fit measurement. Only a definition dispatch exists for this lane; no native graph edits, numerical dispatch claim or review approval. Feedback must bind the final results hash.\n\nLicence blocker for distribution: Teeth3DS source licence unresolved; keep local derived anatomy private. No mail, publishing, push or source-checkout changes. The figures/certificates are research diagnostics, not clinical recommendations.\n"
    (ROOT / 'HANDOFF_R3.md').write_text(h3)
    (ROOT / 'HANDOFF.md').write_text(h3)
    state('FOUNDATION_COMPLETE_PENDING_REVIEW', f"{r['tests']['tests']} tests; 72 designs; no full PASS; R2 gain refuted as joint-fit claim by R3", 'Independent review; next preregister joint min/max-film and ball access on a patient-linked measured preparation')
    files = []
    for pattern in ['gencad_bench/**/*.py', 'scripts/*.py', 'tests/*.py', '*.py', '*.sh', '*.md', '*.json', 'data/*.json', 'figures/*', 'rounds/*/results.json']:
        files.extend(ROOT.glob(pattern))
    files = sorted(set((p for p in files if p.is_file() and p.name not in ['ARTIFACTS.json', 'GRAPH_FEEDBACK.json', 'CURRENT_WORK_STATE.json'])))
    dump(ROOT / 'ARTIFACTS.json', dict(created_utc=now(), scope='Own code, protocols, current reports, figures and round results; excludes mutable feedback/state and this inventory', files=[dict(path=str(p.relative_to(ROOT)), bytes=p.stat().st_size, sha256=sha(p)) for p in files], lane_data=[dict(path=str(p), bytes=p.stat().st_size, sha256=sha(p)) for p in sorted(DATA.glob('*.npz'))]))
    print(json.dumps(dict(finalized=True, original_R1_reproduced=consistency, tests=r['tests'], round3=r3summary), indent=2))
if __name__ == '__main__':
    main()
